<script setup>
import {ref,reactive,onMounted,onBeforeUnmount,computed} from 'vue';
import {api,resizeImage} from '../api.js';
import {session,loadProfile} from '../auth.js';
import {enablePush,disablePush,installAvailable,installApp} from '../pwa.js';
import {useRoute} from 'vue-router';
import {CITIES} from '../options.js';
const route=useRoute();
const loading=ref(true),error=ref(''),notice=ref(''),busy=ref(''),pushKey=ref(''),emailAvailable=ref(false),verification=ref(null),blocks=ref([]),billing=ref(null),plans=ref([]),extraTrips=ref(false);
const form=reactive({emailMatches:false,emailMessages:false,emailSessions:false,emailStreaks:false,pushEnabled:false,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,reminderHour:20});
const trip=reactive({city:'',arrival:''});
const price=computed(()=>{
  const p=billing.value?.price;if(!p)return '';
  const formatter=new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency});
  const zero=new Set(['bif','clp','djf','gnf','jpy','kmf','krw','mga','pyg','rwf','ugx','vuv','xaf','xof','xpf']);
  const scale=zero.has(p.currency)?1:p.currency==='isk'?100:10**formatter.resolvedOptions().maximumFractionDigits;
  return formatter.format(p.amount/scale)+' / '+(p.intervalCount>1?p.intervalCount+' ':'')+p.interval;
});
async function load(){
  loading.value=true;error.value='';
  try{
    const s=await api('/api/settings');Object.assign(form,s.settings);pushKey.value=s.pushKey;emailAvailable.value=s.emailAvailable;
    verification.value=await api('/api/verification');blocks.value=(await api('/api/settings/blocks')).blocks;
    billing.value=await api('/api/billing/config');plans.value=(await api('/api/trips')).plans;
  }catch(e){error.value=e.message;}finally{loading.value=false;}
}
async function task(name,fn){if(busy.value)return;busy.value=name;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value='';}}
async function save(){await task('save',async()=>{await api('/api/settings',{method:'PUT',body:form});notice.value='Saved.';});}
async function push(){await task('push',async()=>{if(form.pushEnabled){await disablePush();form.pushEnabled=false;}else{await enablePush(pushKey.value);form.pushEnabled=true;}await api('/api/settings',{method:'PUT',body:form});});}
async function verify(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const expectedUserId=session.user.id;await task('verification',async()=>{const blob=await resizeImage(file);await api('/api/verification',{method:'POST',body:blob,raw:'image/jpeg',expectedUserId});verification.value=await api('/api/verification');notice.value='Submitted for review.';});}
async function withdraw(){await task('verification',async()=>{await api('/api/verification',{method:'DELETE'});verification.value=await api('/api/verification');});}
async function exportData(){const expectedUserId=session.user.id;await task('export',async()=>{const manifest=await api('/api/export',{expectedUserId});const data={exportedAt:new Date().toISOString(),account:manifest.account};for(const section of manifest.sections){data[section]=[];let offset=0,more=true;while(more){const page=await api('/api/export?section='+encodeURIComponent(section)+'&offset='+offset,{expectedUserId});data[section].push(...page.records);more=page.hasMore;offset=page.nextOffset;}}const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='pacemate-data-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='Download ready.';});}
async function unblock(member){await task('blocks',async()=>{await api('/api/settings/blocks/'+encodeURIComponent(member.id),{method:'DELETE'});blocks.value=blocks.value.filter(b=>b.id!==member.id);});}
async function payment(action){await task('billing',async()=>{const {url}=await api('/api/billing/'+action,{method:'POST',body:{}});const target=new URL(url);if(target.protocol!=='https:'||!['checkout.stripe.com','billing.stripe.com'].includes(target.hostname))throw new Error('Invalid payment destination.');window.location.assign(url);});}
async function addTrip(){await task('trips',async()=>{await api('/api/trips',{method:'POST',body:trip});trip.city='';trip.arrival='';plans.value=(await api('/api/trips')).plans;});}
async function removeTrip(plan){await task('trips',async()=>{await api('/api/trips/'+plan.id,{method:'DELETE'});plans.value=plans.value.filter(p=>p.id!==plan.id);});}
async function arrived(plan){await task('trips',async()=>{await api('/api/trips/arrive',{method:'POST',body:{tripId:plan.id}});await loadProfile();plans.value=(await api('/api/trips')).plans;});}
let paymentTimer;
onMounted(async()=>{await load();if(route.query.checkout==='success'&&billing.value?.enabled&&!billing.value.active){let attempts=0;notice.value='Checking subscription…';paymentTimer=setInterval(async()=>{try{billing.value=await api('/api/billing/config');if(billing.value.active){notice.value='Subscription active.';clearInterval(paymentTimer);}else if(++attempts>=10){notice.value='Subscription confirmation is pending. Refresh shortly.';clearInterval(paymentTimer);}}catch(e){error.value=e.message;clearInterval(paymentTimer);}},3000);}});
onBeforeUnmount(()=>clearInterval(paymentTimer));
</script>
<template><div class="settings"><div class="row heading"><RouterLink to="/app/profile" class="btn ghost sm" aria-label="Back to profile">←</RouterLink><h1>Settings</h1></div><p v-if="error" class="err" role="alert">{{ error }}</p><p v-if="notice" class="ok" role="status">{{ notice }}</p><div v-if="loading" class="spinner"></div><template v-else>
<section class="card"><h2>Notifications</h2><form @submit.prevent="save"><fieldset><legend>Email</legend><p v-if="!emailAvailable" class="mute small">Email delivery is awaiting provider setup. Your preferences will be saved.</p><label class="toggle"><span>New matches</span><input v-model="form.emailMatches" type="checkbox"></label><label class="toggle"><span>New messages</span><input v-model="form.emailMessages" type="checkbox"></label><label class="toggle"><span>Sessions and account updates</span><input v-model="form.emailSessions" type="checkbox"></label><label class="toggle"><span>Streak reminders</span><input v-model="form.emailStreaks" type="checkbox"></label></fieldset><div class="toggle"><b>Browser push</b><button class="btn ghost sm" type="button" :disabled="!!busy||(!form.pushEnabled&&!pushKey)" @click="push">{{ form.pushEnabled?'Turn off':'Enable' }}</button></div><div class="row"><label class="field grow"><span>Timezone</span><input v-model="form.timezone" maxlength="60" required></label><label class="field" style="width:140px"><span>Remind me at</span><select v-model.number="form.reminderHour"><option v-for="n in 24" :key="n" :value="n-1">{{ String(n-1).padStart(2,'0') }}:00</option></select></label></div><button class="btn sm" :disabled="!!busy">Save</button></form></section>
<section class="card"><div class="row between"><h2>Profile verification</h2><span v-if="verification?.verified" class="tag">✓ Verified</span><span v-else-if="verification?.request" class="tag">{{ verification.request.status }}</span></div><button v-if="verification?.verified" class="link small" :disabled="!!busy" @click="withdraw">Remove verification</button><template v-if="!verification?.verified"><p v-if="verification?.request?.status==='pending'">Your selfie is awaiting review.</p><template v-else><p class="small mute">Upload a clear selfie holding up three fingers. An administrator will compare it with your profile photos. Your selfie stays private and is deleted after review.</p><label class="btn ghost sm"><input type="file" class="sr-only" accept="image/jpeg,image/png,image/webp" :disabled="!!busy" @change="verify">Submit selfie</label></template><button v-if="verification?.request?.status==='pending'" class="link small" :disabled="!!busy" @click="withdraw">Withdraw request</button><p v-if="verification?.request?.note" class="small">{{ verification.request.note }}</p></template></section>
<section v-if="billing?.enabled||billing?.active" class="card"><div class="row between"><h2>Pacemate Plus</h2><span v-if="billing.active" class="tag">Active</span></div><p class="small">See who liked you and plan trips to multiple cities. Likes remain unlimited for everyone.</p><p v-if="!billing.active"><b>{{ price }}</b></p><button class="btn sm" :disabled="!!busy" @click="payment(billing.active?'portal':'checkout')">{{ billing.active?'Manage subscription':'Subscribe' }}</button><button v-if="!billing.active&&billing.hasCustomer" class="link small" style="margin-left:12px" :disabled="!!busy" @click="payment('portal')">Manage billing</button></section>
<section v-if="billing?.active||plans.length" class="card"><h2>Travel plans</h2><ul class="plain"><li v-for="plan in plans" :key="plan.id" class="plan"><div><b>{{ plan.city }}</b><span class="small mute">{{ plan.arrival }}</span></div><button v-if="plan.arrival<=new Date().toISOString().slice(0,10)" class="btn ghost sm" :disabled="!!busy" @click="arrived(plan)">I’ve arrived</button><button class="link small" :disabled="!!busy" @click="removeTrip(plan)">Remove</button></li></ul><form v-if="billing?.active" @submit.prevent="addTrip"><label class="field"><span>City</span><input v-model="trip.city" list="travel-cities" maxlength="60" required></label><datalist id="travel-cities"><option v-for="c in CITIES" :key="c" :value="c"/></datalist><label class="field"><span>Arrival</span><input v-model="trip.arrival" type="date" :min="new Date().toISOString().slice(0,10)" required></label><button class="btn ghost sm" :disabled="!!busy">Add city</button></form></section>
<section class="card"><h2>Blocked members</h2><p v-if="!blocks.length" class="mute small">No blocked members.</p><ul class="plain"><li v-for="member in blocks" :key="member.id" class="toggle"><span>{{ member.name }}</span><button class="link small" :disabled="!!busy" @click="unblock(member)">Unblock</button></li></ul></section>
<section class="card"><h2>Your data</h2><button class="btn ghost sm" :disabled="!!busy" @click="exportData">{{ busy==='export'?'Preparing…':'Download my data' }}</button></section><section v-if="installAvailable" class="card"><h2>Pacemate on your phone</h2><button class="btn ghost sm" @click="installApp">Install app</button></section><a class="support" href="mailto:trypacemate@gmail.com">Contact support</a>
</template></div></template>
<style scoped>h1{font-size:30px}h2{font-size:21px;margin-bottom:14px}.heading{margin-bottom:20px}.settings>section{margin-bottom:14px}.toggle,.between{display:flex;align-items:center;justify-content:space-between;gap:12px}.toggle{padding:10px 0}.toggle input{width:20px;height:20px}fieldset{border:0;padding:0;margin:0 0 14px}legend{font-weight:700}.plain{list-style:none;padding:0;margin:0}.plan{display:flex;align-items:center;gap:10px;padding:10px 0}.plan>div{flex:1;display:flex;flex-direction:column}.support{display:block;text-align:center;padding:10px}.settings .card .field{margin-top:12px}</style>
